import v from './src/domain/vocabulary/data/vocabulary.json' with {type:'json'};
const base = [...'มนงยวกดบชซพฟ', ...'าีะัิุู'];
const steps = [
 ['L6', [...'ค','ึ','ื','อ']],
 ['L7', [...'ทฮ','เ']],
 ['L8', [...'รล','แ']],
 ['L9', [...'จตป','โ']],
 ['L10',[...'ไใ','ๆ']],
 ['L11',[...'อ']],
];
let taught = new Set(base);
